#include "performance.h"
#include <cassert>
#include <cmath>
#include <cstdio>
#include <memory>
int main(){using namespace groove;auto p=std::make_unique<ProjectState>();make_empty_project(*p);p->routing.groups[0].members=1;p->routing.groups[0].insert_fx[0]=1;p->routing.groups[0].insert_fx[1]=.2f;p->morph_enabled=true;p->morph_position=.5f;for(unsigned t=0;t<16;++t){p->morph_a[t].values[morph_index(385)]=.2f;p->morph_b[t].values[morph_index(385)]=.8f;}auto track=track_at(*p,0,0);track.steps[0].enabled=true;track.steps[0].locks[0]={385,.3f,true};track.steps[1].enabled=true;
 auto e=std::make_unique<Engine>(8000);float audio[128];assert(e->stage_project(*p));e->render(audio,0);e->render(audio,64);assert(fabsf(e->group_effect_target(0,1)-.5f)<.001f);assert(e->submit({CommandType::Start,0,0,0}));e->render(audio,64);assert(fabsf(e->group_effect_target(0,1)-.3f)<.001f);for(unsigned i=0;i<18;++i)e->render(audio,64);assert(fabsf(e->group_effect_target(0,1)-.5f)<.001f);auto ui=std::make_unique<Performance>(*e,*p);ui->set_mode(UiMode::Routing);assert(ui->soft_key(0));ui->set_shift(true);assert(ui->pad(15,0x10,3500));assert(ui->pad(15,0x20,0));assert(ui->selected_step()==3);assert(ui->knob(3,1000));bool found=false;for(const auto& lock:track_at(*p,0,0).steps[3].locks)if(lock.enabled && lock.id==386)found=true;assert(found);ui->set_shift(false);assert(ui->knob(2,1000));assert(p->routing.groups[0].insert_fx[1]>.2f);assert(ui->set_parameter(group_fx_id(0,0),0));assert(ui->soft_key(1) && ui->group_fx_slot()==1);assert(ui->knob(1,1000));assert(p->routing.groups[0].insert_fx[4]==1);ui->set_shift(true);assert(ui->soft_key(5));assert(p->routing.groups[0].insert_fx[0]==1 && p->routing.groups[0].insert_fx[4]==0);ui->set_shift(false);e->render(audio,64);assert(e->group_effect_target(0,0)==1 && e->group_effect_target(0,4)==0);assert(ui->undo());assert(p->routing.groups[0].insert_fx[0]==0 && p->routing.groups[0].insert_fx[4]==1);e->render(audio,64);assert(e->group_effect_target(0,0)==0 && e->group_effect_target(0,4)==1);puts("group FX engine morph, step lock, restore and UI passed");}
